"""Write docs/metrics.md from relsynth.quality.registry (the single source of the
metric definitions) and relsynth.quality.DEFAULTS:

    python docs/make_metrics_reference.py
"""
from __future__ import annotations

from pathlib import Path

from relsynth.quality import DEFAULTS, METRICS, SCHEMA_VERSION
from relsynth.quality.registry import SCORECARD_AREAS

HERE = Path(__file__).resolve().parent

INTRO = f"""# Quality metrics (report {SCHEMA_VERSION})

<!-- generated by docs/make_metrics_reference.py from src/relsynth/quality/registry.py: do not edit -->

The 2.0 quality report compares synthetic tables with the real ones they were
fitted on. Every check names a metric defined below, the value, the limit, how
the limit was calibrated, the check's level `alpha` (the probability of failing
when the synthetic data is a draw of the real data's law) and the confidence
level. The checks are grouped in a **quality vector** with three areas:
fidelity, utility and integrity. Privacy metrics belong to the privacy report
(roadmap thread T06); the 1.0 privacy items are passed through without an area.

```python
import relsynth as rs
q = rs.assess_quality(spec, synthetic, holdout=None, config={{"classifier": "logistic"}})
q.vector          # {{"fidelity": {{...}}, "utility": {{...}}, "integrity": {{...}}, "verdict": {{...}}}}
q.require()       # quality gate: raises QualityGateError when an area fails
q.to_json("quality.json")
```

```bash
relsynth evaluate spec.yaml --synthetic csv:out/ --quality quality.json [--quality-config q.yaml] [--holdout csv:holdout/]
```

The report validates against
[`quality-report-2.0.schema.json`](../src/relsynth/quality/schema/quality-report-2.0.schema.json).

## How a limit is set

For a metric T (a distance with ideal value 0, or a detection accuracy with
ideal value 0.5) the null hypothesis is that the synthetic rows are a draw of
the real data's law. The real data supplies draws of T under that hypothesis:

1. Split the real rows at random into two halves. Rows that share an ancestor
   row (the orders and order lines of one customer) go to the same half: the
   cluster is the root of the table's anchor chain (`calibrate.anchor_chain`).
2. Compute T between the halves; repeat `null_splits` times (single-table
   metrics) or `multi_splits` times (multi-table and utility metrics).
3. The limit is the one-sided normal prediction bound for one more draw at the
   `confidence` level, computed on log T for distances, and rescaled from the
   split sizes (a', b') to the compared sizes (a, b) by
   kappa = sqrt((1/a + 1/b) / (1/a' + 1/b')) (Prop. 109).
4. The limit is never below the metric's practical **tolerance**: a difference
   below it is accepted however large the data. Tolerances are judgement
   calls, not derived values; set your own with `tolerances`.

`alpha` of a check is the probability, under the same predictive law, that T
exceeds the final limit; it is at most 1 - confidence.

## Pass rules (Prop. 111)

The level `1 - area_confidence` of an area is split in two halves. An area
fails when its failed checks exceed the `1 - (1 - area_confidence)/2`
quantile of the Poisson-binomial law of false failures (the sum of
independent Bernoulli(alpha_i)), **or** when one failed check is severe: its
`p_value` (the null probability of a value at least as large; computed for
distances calibrated on the log scale, not for signed gaps) is below
`(1 - area_confidence) / (2 m)` for the area's m calibrated checks. The
first half catches a defect that pushes many checks slightly over their
limits, the second a defect that a few checks see clearly. A check without a
level (a fixed limit, an identity such as foreign-key integrity) tolerates no
failure, so integrity passes only when every integrity check passes. The
verdict passes when every area passes. **No weighted overall score is
computed**; the report shows each area's checks, failures, expected false
failures, tolerated failures and severe failures.

The 1.0 scorecard items keep their limits and outcomes and are placed in an
area: {", ".join(f"`{k}` -> {v}" for k, v in SCORECARD_AREAS.items())}; every
other 1.0 item is fidelity.

## Settings

| Setting | Default | Meaning |
|---|---|---|
"""

SETTINGS = {
    "confidence": "level of each calibrated check",
    "area_confidence": "level of each area's pass rule",
    "null_splits": "real-vs-real splits for single-table metrics",
    "multi_splits": "splits for multi-table and utility metrics",
    "max_rows": "rows per table for column, marginal and k-hop metrics (seeded sample)",
    "max_rows_model": "rows per side for precision/recall, detection and utility",
    "k3_max": "3-way marginals per table (seeded sample of the triples)",
    "max_hops": "longest foreign-key path for k-hop trends and fan-out (1 or 2)",
    "classifier": "aggregation detection: `logistic` (no extra dependency) or `xgboost` (`relsynth[benchmark]`)",
    "targets": "`{table: column}` utility targets (default: a heuristic, see `utility.pick_target`)",
    "mt_targets": "`{parent table: column}` multi-table utility targets",
    "tolerances": "`{metric id: floor}` practical tolerances",
    "calibrate": "`false`: limits are the tolerances only (fast, no null calibration)",
    "scale": "expected synthetic/real size: a number or `{default, tables}` as in the spec's `synthesis.scale` "
             "(copied tables keep their size, facts follow their anchor). Per-parent counts are divided by the "
             "expected change of rows per parent (Prop. 113). `None`: 1, or the spec's scale in `assess_quality`",
    "seed": "seed of every sample, split and fold",
}


def main():
    lines = [INTRO.rstrip("\n")]
    for k, v in DEFAULTS.items():
        lines.append(f"| `{k}` | `{v!r}` | {SETTINGS[k]} |")
    for area in ("fidelity", "utility"):
        lines += ["", f"## {area.capitalize()} metrics", ""]
        for mid, m in METRICS.items():
            if m["area"] != area:
                continue
            lines += [f"### `{mid}`: {m['name']}", "",
                      m["definition"], "",
                      f"- Scope: {m['scope']}; range {m['range']}; ideal {m['center']}; lower is better.",
                      f"- Tolerance: {m['tolerance']}; null: {m['null']}.",
                      f"- Reference: {m['reference']}.", ""]
    lines += ["## Integrity", "",
              "Integrity checks come from the 1.0 scorecard: foreign-key integrity, rule violations, unique-key "
              "duplicates, tree cycles and rows the sampler removed. They are identities with no sampling noise, "
              "so each must pass.", "",
              "## Benchmark summaries", "",
              "`benchmark.syntherela` holds the numbers SyntheRela (Hudovernik et al., TMLR 2026) reports, for "
              "comparison with published results: cardinality similarity (1 - KS of per-parent child counts, per "
              "relationship), k-hop trend scores (mean SDMetrics column-pair trend score per hop count) and "
              "C2ST-Agg accuracy per parent table and its maximum. They are not checks. "
              "See [benchmarks/syntherela](../benchmarks/syntherela/README.md) for relsynth's results.", ""]
    (HERE / "metrics.md").write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
